const ok = pm.response.code === 200;

pm.test("Expected status: 200", () => pm.expect(pm.response.code).to.eql(200));

if (!ok) {
  console.error("Admin login failed, aborting run:", pm.response.code, pm.response.text());
  pm.execution.setNextRequest(null); // stops the collection run
} else {
  let j = {};
  try { j = pm.response.json(); } catch (e) {}

  pm.test("Returns a JWT (3 parts)", () => {
    pm.expect(j.token).to.be.a('string');
    pm.expect(j.token.split('.')).to.have.lengthOf(3);
  });

  if (j.token && j.token.split('.').length === 3) {
    // saved before the next request starts
    pm.collectionVariables.set('adminToken', j.token);
  } else {
    pm.execution.setNextRequest(null); // 200 but no valid token: abort too
  }
}

const cv = pm.collectionVariables;
const base = pm.variables.replaceIn('{{baseUrl}}');
const runId = Date.now();
const ALN = 'abcdefghjkmnpqrstuvwxyz23456789';
const rnd = n => Array.from({ length: n }, () => ALN[Math.floor(Math.random() * ALN.length)]).join('');

const post = (path, body) => new Promise((resolve, reject) => {
  pm.sendRequest({
    url: base + path,
    method: 'POST',
    header: { 'Content-Type': 'application/json' },
    body: { mode: 'raw', raw: JSON.stringify(body) }
  }, (err, res) => err ? reject(err) : resolve(res));
});

(async () => {
  cv.set('runId', String(runId));

  for (const i of [1, 2, 3]) {
    const email = `qa.client${i}.${runId}.${rnd(4)}@example.com`;
    const password = `Qa!${rnd(6)}9aA`;

    // 1) Register
    const reg = await post('/auth', { email, password });
    if (reg.code >= 300) {
      console.error(`Client ${i} registration failed`, reg.code, reg.text());
      continue;
    }

    // 2) Login
    const login = await post('/auth/login', { email, password });
    if (login.code !== 200) {
      console.error(`Client ${i} login failed`, login.code, login.text());
      continue;
    }

    cv.set(`clientEmail${i}`, email);
    cv.set(`clientPassword${i}`, password);
    cv.set(`token${i}`, login.json().token);
  }

  cv.set('setupDone', '1');
  console.log('Clients ready:', [1, 2, 3].map(i => cv.get(`clientEmail${i}`)));
})();

const cv = pm.collectionVariables;
const base = pm.variables.replaceIn('{{baseUrl}}');
const runId = cv.get('runId') || String(Date.now());

const categories = [
  `QA Gift Cards ${runId}`,
  `QA Subscriptions ${runId}`,
  `QA Software ${runId}`
];

const post = (path, body) => new Promise((resolve, reject) => {
  pm.sendRequest({
    url: base + path,
    method: 'POST',
    header: {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + cv.get('adminToken')
    },
    body: { mode: 'raw', raw: JSON.stringify(body) }
  }, (err, res) => err ? reject(err) : resolve(res));
});

(async () => {
  for (const [idx, name] of categories.entries()) {
    const i = idx + 1;
    const res = await post('/admin/categories', { name });

    if (res.code >= 300) {
      console.error(`Category ${i} creation failed`, res.code, res.text());
      cv.set(`categoryError${i}`, `${res.code}: ${res.text().slice(0, 200)}`);
      cv.unset(`categoryId${i}`);
      continue;
    }

    cv.unset(`categoryError${i}`);
    cv.set(`categoryId${i}`, String(res.json().id));
    cv.set(`categoryName${i}`, name);
  }

  // keep compatibility with your existing single-category variable
  if (cv.get('categoryId1')) cv.set('categoryId', cv.get('categoryId1'));
  console.log('Categories ready:', [1, 2, 3].map(i => cv.get(`categoryId${i}`)));
})();

const cv = pm.collectionVariables;

[1, 2, 3].forEach(i => {
  pm.test(`Category ${i}: id and name stored`, () => {
    pm.expect(cv.get(`categoryId${i}`), cv.get(`categoryError${i}`) || 'id').to.be.a('string').and.not.empty;
    pm.expect(cv.get(`categoryName${i}`), 'name').to.be.a('string').and.have.length.of.at.most(100);
  });
});

pm.test('All 3 category ids and names are distinct', () => {
  const ids = [1, 2, 3].map(i => cv.get(`categoryId${i}`));
  const names = [1, 2, 3].map(i => cv.get(`categoryName${i}`));
  pm.expect(new Set(ids).size).to.equal(3);
  pm.expect(new Set(names).size).to.equal(3);
});

