(async () => {
  for (const [idx, p] of products.entries()) {
    const i = idx + 1;
    const sku = `QA-${runId}-P${i}`;
    const { cat, ...data } = p;
    const body = { sku, active: true, ...data };

    const catId = cat ? cv.get(`categoryId${cat}`) : null;
    if (catId) body.categoryId = Number(catId);

    const res = await post('/admin/products', body);
    if (res.code >= 300) {
      console.error(`Product ${i} creation failed`, res.code, res.text());
      cv.set(`productError${i}`, `${res.code}: ${res.text().slice(0, 200)}`);
      continue;
    }

    cv.unset(`productError${i}`);
    cv.set(`productId${i}`, String(res.json().id));
    cv.set(`productSku${i}`, sku);
    cv.set(`productName${i}`, p.name);
    cv.set(`productType${i}`, p.type);
    cv.set(`productPrice${i}`, String(p.salePrice));
    if (catId) cv.set(`productCategoryId${i}`, catId); else cv.unset(`productCategoryId${i}`);
  }

  // keep compatibility with existing single-product variables
  cv.set('prodSku', cv.get('productSku1'));
  if (!cv.get('tipoValido')) cv.set('tipoValido', 'GIFT_CARD');
  console.log('Products ready:', [1, 2, 3, 4, 5].map(i => cv.get(`productSku${i}`)));
})();

