const cv = pm.collectionVariables;
const base = pm.variables.replaceIn('{{baseUrl}}');
const runId = cv.get('runId') || String(Date.now());
const ALN = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
const rnd = n => Array.from({ length: n }, () => ALN[Math.floor(Math.random() * ALN.length)]).join('');

// product index -> number of codes (4 and 5 intentionally get none)
const plan = { 1: 10, 2: 150, 3: 10, 4: 0, 5: 0 };

const post = (path, body) => new Promise((resolve, reject) => {
  pm.sendRequest({
    url: base + path,
    method: 'POST',
    header: {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + cv.get('adminToken')
    },
    body: { mode: 'raw', raw: JSON.stringify(body) }
  }, (err, res) => err ? reject(err) : resolve(res));
});

(async () => {
  for (const [key, count] of Object.entries(plan)) {
    const i = Number(key);

    // reset state from previous runs
    cv.set(`codesExpected${i}`, String(count));
    cv.unset(`codesSaved${i}`);
    cv.unset(`codesError${i}`);
    cv.unset(`productCodes${i}`);

    if (count === 0) continue;

    const productId = cv.get(`productId${i}`);
    if (!productId) {
      cv.set(`codesError${i}`, `product ${i} has no id (creation failed)`);
      continue;
    }

    // each code: 5-50 chars, unique per run/product/index
    const codes = Array.from({ length: count }, (_, k) =>
      `QA-${runId}-P${i}-${String(k + 1).padStart(4, '0')}-${rnd(4)}`);

    const res = await post(`/admin/products/${productId}/codes`, { codes: codes });
    if (res.code !== 201) {
      console.error(`Codes for product ${i} failed`, res.code, res.text());
      cv.set(`codesError${i}`, `${res.code}: ${res.text().slice(0, 200)}`);
      continue;
    }

    let saved;
    try { const j = res.json(); saved = j.savedCount; } catch (e) {}
    cv.set(`codesSaved${i}`, String(saved));
    cv.set(`productCodes${i}`, JSON.stringify(codes)); // plain-text codes, handy for later tests
  }

  console.log('Codes saved:', Object.keys(plan).map(i => `P${i}=${cv.get(`codesSaved${i}`) ?? '-'}`).join(' '));
})();

const cv = pm.collectionVariables;

[1, 2, 3].forEach(i => {
  pm.test(`Product ${i}: all codes were saved`, () => {
    const msg = cv.get(`codesError${i}`) || 'saved count';
    pm.expect(cv.get(`codesSaved${i}`), msg).to.be.a('string');
    pm.expect(cv.get(`codesSaved${i}`), 'saved vs expected').to.equal(cv.get(`codesExpected${i}`));
  });

  pm.test(`Product ${i}: stored plain codes match the count`, () => {
    pm.expect(JSON.parse(cv.get(`productCodes${i}`) || '[]')).to.have.lengthOf(Number(cv.get(`codesExpected${i}`)));
  });
});

pm.test('Products 4 and 5 have no codes', () => {
  [4, 5].forEach(i => {
    pm.expect(cv.get(`codesSaved${i}`), `product ${i}`).to.be.undefined;
    pm.expect(cv.get(`codesError${i}`), `product ${i}`).to.be.undefined;
  });
});

const cv = pm.collectionVariables;

const base = pm.variables.replaceIn('{{baseUrl}}');

const original = String(cv.get('clientEmail1') || '');
const password = String(cv.get('clientPassword1') || '');

// body attempt (the request itself): UPPERCASE
pm.variables.set('dupEmailUpper', original.toUpperCase());
pm.variables.set('dupPassword', password);

// extra attempt sent from here: lowercase (same as stored in DB)
cv.unset('dupLowerStatus');
cv.unset('dupLowerBody');

pm.sendRequest({
  url: base + '/auth',
  method: 'POST',
  header: { 'Content-Type': 'application/json' },
  body: { mode: 'raw', raw: JSON.stringify({ email: original.toLowerCase(), password }) }
}, (err, res) => {
  if (err || !res) {
    console.error('Lowercase attempt failed to send', err);
    cv.set('dupLowerStatus', 'ERR');
    return;
  }
  cv.set('dupLowerStatus', String(res.code));
  cv.set('dupLowerBody', res.text().slice(0, 200));
});

